FUNCTION UNDER TEST:
Name: buffer_slice
Signature: buffer_t* buffer_slice(buffer_t *buf, size_t from, ssize_t to)
Description: /**
 * @brief Create a new buffer containing a slice of the input buffer.
 *
 * Allocates and returns a new buffer with data copied from the specified
 * range [from, to) of the input buffer. If to is negative, it is interpreted
 * as an offset from the end of the buffer. Returns NULL if the range is invalid.
 *
 * @param buf Pointer to the source buffer. Must not be NULL and must contain a valid null-terminated string in data.
 * @param from Starting index of the slice (inclusive). Must be less than or equal to the buffer length.
 * @param to Ending index of the slice (exclusive). If negative, counts from the end; must not be less than from.
 *
 * @return Pointer to a newly allocated buffer containing the slice, or NULL if the range is invalid or allocation fails.
 *
 * @note Memory: Caller must free the returned buffer.
 * @see buffer_new_with_size
 */
Dependencies: buffer_new_with_size

FUNCTION IMPLEMENTATION:
```c
// C program for the function called buffer_slice
// Contains target function implementation and dependency signatures

#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <ctype.h>
#include <sys/types.h>
#include "buffer.h"

// Forward declarations for dependency functions
buffer_t *
buffer_new_with_size(size_t n);

// Target function implementation
buffer_t *
buffer_slice(buffer_t *buf, size_t from, ssize_t to) {
  size_t len = strlen(buf->data);

  // bad range
  if (to < from) return NULL;

  // relative to end
  if (to < 0) to = len - ~to;

  // cap end
  if (to > len) to = len;

  size_t n = to - from;
  buffer_t *self = buffer_new_with_size(n);
  memcpy(self->data, buf->data + from, n);
  return self;
}

